create extension if not exists "pgcrypto";
create table public.categories(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid(),name text not null,is_default boolean default false,created_at timestamptz default now(),unique(user_id,name));
create table public.tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid(),title text not null,description text,category_id uuid references public.categories(id),category_name text,priority text not null default 'Medium' check(priority in ('Critical','High','Medium','Low')),status text not null default 'Not Started' check(status in ('Not Started','In Progress','Waiting for Approval','Waiting for Others','Completed','Cancelled')),start_date date,deadline date,reminder_time time default '09:00',responsible_person text,department text,notes text,external_links text,recurrence text,deadline_change_reason text,completed_at timestamptz,completion_notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.daily_activities(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid(),title text not null,description text,category_id uuid references public.categories(id),category_name text,activity_date date not null,start_time time,end_time time,notes text,created_at timestamptz default now());
create table public.follow_ups(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid(),task_id uuid not null references public.tasks(id) on delete cascade,person_responsible text,waiting_for text not null,follow_up_date date not null,notes text,outcome text,created_at timestamptz default now());
create table public.daily_summaries(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid(),summary_date date not null,summary_type text not null check(summary_type in ('start','end')),notes text,created_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid(),title text not null,body text,is_read boolean default false,created_at timestamptz default now());
create table public.task_history(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid(),task_id uuid references public.tasks(id) on delete cascade,action text not null,details text,old_value jsonb,new_value jsonb,created_at timestamptz default now());
create table public.user_settings(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() unique,dashboard_name text default 'HR GOKUL WORKSPACE',company_name text default 'Asasi Group',designation text default 'HR Generalist',default_reminder_time time default '09:00',updated_at timestamptz default now());
create index tasks_owner_deadline_idx on public.tasks(user_id,deadline); create index activities_owner_date_idx on public.daily_activities(user_id,activity_date); create index notifications_owner_read_idx on public.notifications(user_id,is_read);
alter table public.categories enable row level security; alter table public.tasks enable row level security; alter table public.daily_activities enable row level security; alter table public.follow_ups enable row level security; alter table public.daily_summaries enable row level security; alter table public.notifications enable row level security; alter table public.task_history enable row level security; alter table public.user_settings enable row level security;
grant usage on schema public to authenticated;
grant select, insert, update, delete on public.categories, public.tasks, public.daily_activities, public.follow_ups, public.daily_summaries, public.notifications, public.task_history, public.user_settings to authenticated;
do $$ declare t text; begin foreach t in array array['categories','tasks','daily_activities','follow_ups','daily_summaries','notifications','task_history','user_settings'] loop execute format('create policy "owner access" on public.%I for all using (user_id = auth.uid()) with check (user_id = auth.uid())',t); end loop; end $$;
create or replace function public.log_task_change() returns trigger language plpgsql security definer set search_path=public as $$begin if tg_op='INSERT' then insert into task_history(user_id,task_id,action,details,new_value) values(new.user_id,new.id,'task_created',new.title,to_jsonb(new)); elsif tg_op='UPDATE' then insert into task_history(user_id,task_id,action,details,old_value,new_value) values(new.user_id,new.id,case when old.status<>new.status and new.status='Completed' then 'task_completed' when old.status<>new.status then 'status_changed' when old.deadline is distinct from new.deadline then 'deadline_changed' else 'task_updated' end,new.deadline_change_reason,to_jsonb(old),to_jsonb(new)); end if; return new; end$$;
create trigger task_audit after insert or update on public.tasks for each row execute function public.log_task_change();
-- Standard categories are copied into each account by a client or sign-up trigger. No tasks or activities are seeded.
